import java.util.*;
import java.util.function.*;
import java.util.stream.*;

public class Col2 {
    /** Collects strings into a "a;b;c" string, built by hand to show the four parts. */
    static Collector<String, StringJoiner, String> semicolon() {
        return Collector.of(
            () -> new StringJoiner(";"),          // supplier: new mutable container
            StringJoiner::add,                    // accumulator: fold one element in
            StringJoiner::merge,                  // combiner: merge two containers (parallel)
            StringJoiner::toString);              // finisher: container -> result
    }

    /** Keeps the N largest values. */
    static Collector<Integer, ?, List<Integer>> topN(int n) {
        return Collector.of(
            () -> new PriorityQueue<Integer>(),
            (pq, x) -> { pq.add(x); if (pq.size() > n) pq.poll(); },
            (a, b) -> { a.addAll(b); while (a.size() > n) a.poll(); return a; },
            pq -> pq.stream().sorted(Comparator.reverseOrder()).toList());
    }

    public static void main(String[] args) {
        System.out.println(Stream.of("a", "b", "c").collect(semicolon()));
        System.out.println(Stream.of(5, 1, 9, 3, 7, 8).collect(topN(3)));
        System.out.println(IntStream.rangeClosed(1, 1000).parallel().boxed().collect(topN(3)));
        System.out.println(semicolon().characteristics());
        // toMap with null value
        try { Stream.of("a").collect(Collectors.toMap(s -> s, s -> null)); }
        catch (NullPointerException e) { System.out.println("toMap: null value -> NPE"); }
        // groupingBy ignores null? no: null key is rejected
        try { Stream.of("a").collect(Collectors.groupingBy(s -> (String) null)); }
        catch (NullPointerException e) { System.out.println("groupingBy: " + e.getMessage()); }
        // unmodifiable
        List<Integer> u = Stream.of(1, 2).collect(Collectors.toUnmodifiableList());
        try { u.add(3); }
        catch (UnsupportedOperationException e) { System.out.println("unmodifiable"); }
    }
}
